{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Investment & Plans — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfc;--card:#fff;--muted:#6b7280;--accent:#6a9b6f;--accent-2:#3b82f6;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; color:#0f172a; background:linear-gradient(180deg,var(--bg),#f6fbf6);}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .cta{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}
    .container{max-width:1100px;margin:24px auto;padding:28px}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:28px;align-items:center}
    .hero-card{background:var(--card);padding:26px;border-radius:14px;box-shadow:0 6px 20px rgba(20,20,40,0.06)}
    h1{margin:0 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .toggle{display:flex;align-items:center;gap:12px;background:linear-gradient(180deg,#fff,#fbfffb);padding:14px;border-radius:12px;margin-top:16px}
    .switch{background:#e6eef0;padding:4px;border-radius:999px;width:120px;display:flex;align-items:center;gap:8px;position:relative}
    .switch button{flex:1;background:transparent;border:0;padding:8px 10px;border-radius:999px;cursor:pointer;font-weight:600}
    .switch .knob{position:absolute;left:4px;top:4px;width:52px;height:32px;background:linear-gradient(180deg,var(--accent),#4b7f56);border-radius:999px;transition:transform 320ms cubic-bezier(.2,.9,.2,1);}
    .pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:22px}
    .plan{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--card));padding:18px;border-radius:12px;border:1px solid rgba(10,10,10,0.03)}
    .plan h3{margin:0 0 6px}
    .price{font-size:26px;font-weight:800;color:var(--accent-2);display:flex;align-items:baseline;gap:8px}
    .per{font-size:12px;color:var(--muted)}
    .list{margin:12px 0 16px;padding:0;list-style:none;color:var(--muted)}
    .btn{display:inline-block;padding:10px 14px;border-radius:10px;background:var(--accent);color:white;text-decoration:none;font-weight:700}
    .note{font-size:13px;color:var(--muted);margin-top:12px}
    footer{padding:26px;text-align:center;color:var(--muted)}
    /* SVG background */
    .pattern-wrap{position:absolute;inset:0;pointer-events:none;opacity:0.06}
    @media(max-width:900px){.hero{grid-template-columns:1fr;}.pricing-grid{grid-template-columns:1fr}} 
  </style>
</head>
<body>
  <div class="pattern-wrap" aria-hidden>
    <svg width="100%" height="100%" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <pattern id="p1" width="24" height="24" patternUnits="userSpaceOnUse" patternTransform="rotate(15)">
          <rect width="12" height="12" fill="#cfead4"></rect>
          <circle cx="6" cy="6" r="1.5" fill="#9cc89f"></circle>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#p1)"></rect>
    </svg>
  </div>

  <header>
    <div class="brand">
      <div class="logo">WC</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Practical rhythm coaching</div>
      </div>
    </div>
    <nav aria-label="Main" style="display:flex;align-items:center">
      <a href="index.html">Nest</a>
      <a href="about.html">Story</a>
      <a href="services.html">Care</a>
      <a href="programs.html">Tracts</a>
      <a href="pricing.html" style="color:var(--accent-2);font-weight:800">Invest</a>
      <a href="testimonials.html">Voices</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero">
      <div class="hero-card">
        <h1>Choose the pace that fits: monthly or cohort package</h1>
        <p class="lead">We shape outcomes with habits and simple frameworks — no medical promises, just reliable changes you can track. Pick a rhythm: steady monthly support or a focused cohort package.</p>

        <div class="toggle" role="region" aria-label="Pricing toggle">
          <div style="flex:1">
            <div style="font-weight:700">Billing view</div>
            <div style="color:var(--muted);font-size:13px">Toggle to compare monthly plans vs cohort package totals</div>
          </div>
          <div class="switch" id="billingSwitch">
            <div class="knob" id="knob"></div>
            <button data-mode="monthly" id="btnMonthly">Monthly</button>
            <button data-mode="package" id="btnPackage">Package</button>
          </div>
        </div>

        <div class="pricing-grid">
          <div class="plan">
            <h3>Seed — Habit Starter</h3>
            <div class="price"><span class="num" data-monthly="49" data-package="240">$49</span><span class="per">/mo</span></div>
            <ul class="list"><li>Weekly check-ins</li><li>Habit templates</li><li>Starter toolkit</li></ul>
            <a class="btn" href="{{PRIMARY_CTA_URL}}?plan=seed">Start Seed</a>
            <div class="note">Best for one habit at a time</div>
          </div>

          <div class="plan">
            <h3>Grove — Momentum Cohort</h3>
            <div class="price"><span class="num" data-monthly="129" data-package="600">$129</span><span class="per">/mo</span></div>
            <ul class="list"><li>Cohort rhythm 6 weeks</li><li>Group coaching + templates</li><li>Accountability buddy</li></ul>
            <a class="btn" href="{{PRIMARY_CTA_URL}}?plan=grove">Join Grove</a>
            <div class="note">Designed as a guided cohort (our most popular)</div>
          </div>

          <div class="plan">
            <h3>Orchard — Deep Cohort</h3>
            <div class="price"><span class="num" data-monthly="219" data-package="1000">$219</span><span class="per">/mo</span></div>
            <ul class="list"><li>Extended 12-week cohort</li><li>Personal habit blueprint</li><li>Priority support</li></ul>
            <a class="btn" href="{{PRIMARY_CTA_URL}}?plan=orchard">Reserve Orchard</a>
            <div class="note">For people rebuilding several routines</div>
          </div>
        </div>

      </div>

      <aside style="padding:8px 0 0">
        <div class="hero-card">
          <h3>How the pricing works</h3>
          <p style="color:var(--muted)">Monthly is rolling support. Package numbers show the total investment for a cohort cycle — perfect if you prefer a single payment for a guided series.</p>
          <hr style="border:none;border-top:1px solid #eef4ee;margin:12px 0">
          <div style="display:flex;gap:8px;flex-direction:column">
            <strong>Quick calculator</strong>
            <div style="display:flex;gap:8px;align-items:center">
              <label style="font-size:13px;color:var(--muted)">Plan</label>
              <select id="quickPlan" style="flex:1;padding:8px;border-radius:8px;border:1px solid #e6efe6">
                <option value="seed">Seed</option>
                <option value="grove">Grove</option>
                <option value="orchard">Orchard</option>
              </select>
            </div>
            <div style="display:flex;gap:8px;align-items:center">
              <label style="font-size:13px;color:var(--muted)">Billing</label>
              <button id="quickToggle" style="padding:8px;border-radius:8px;border:1px dashed #cfead4;background:white;cursor:pointer">Monthly</button>
            </div>
            <div style="margin-top:8px">
              <div style="font-size:13px;color:var(--muted)">Estimated payment</div>
              <div style="font-weight:800;font-size:20px" id="quickResult">$49 /mo</div>
            </div>
            <a class="btn" href="{{PRIMARY_CTA_URL}}" style="margin-top:12px">Take the next step</a>
          </div>
        </div>
      </aside>
    </section>

    <section style="margin-top:22px;background:linear-gradient(180deg,#fff,#fbfffb);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(15,23,42,0.04)">
      <h3 style="margin:0 0 8px">Need a custom rhythm?</h3>
      <p style="margin:0;color:var(--muted)">We frequently create bespoke cohort timings and sliding scale options. Call us at <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>

  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto;padding:18px 28px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <div style="color:var(--muted)">Serving {{CITY}}, {{STATE}} • <a href="contact.html">Contact</a></div>
    </div>
  </footer>

  <script>
    // Pricing comparator simple knob control & animated numbers
    (function(){
      const btnMonthly = document.getElementById('btnMonthly');
      const btnPackage = document.getElementById('btnPackage');
      const knob = document.getElementById('knob');
      const nums = Array.from(document.querySelectorAll('.num'));
      const quickToggle = document.getElementById('quickToggle');
      const quickPlan = document.getElementById('quickPlan');
      const quickResult = document.getElementById('quickResult');

      let mode = 'monthly';

      function setMode(newMode, animate=true){
        mode = newMode;
        if(newMode==='package'){
          knob.style.transform = 'translateX(60px)';
        } else {
          knob.style.transform = 'translateX(0)';
        }
        nums.forEach(n => animate ? animateNumber(n, n.dataset[mode]) : setRaw(n, n.dataset[mode]));
        quickToggle.textContent = mode==='monthly' ? 'Monthly' : 'Package';
        updateQuickResult();
      }

      function setRaw(el,val){
        el.textContent = '$' + val;
        const per = el.parentNode.querySelector('.per');
        if(per) per.textContent = mode==='monthly' ? '/mo' : '/cycle';
      }

      function animateNumber(el, target){
        const start = parseFloat(el.textContent.replace(/[^0-9.]/g,'')) || 0;
        const end = parseFloat(target);
        const duration = 420;
        let startTime = null;
        function step(ts){
          if(!startTime) startTime = ts;
          const progress = Math.min((ts - startTime)/duration,1);
          const ease = 1 - Math.pow(1-progress,3);
          const current = Math.round(start + (end - start) * ease);
          el.textContent = '$' + current;
          const per = el.parentNode.querySelector('.per');
          if(per) per.textContent = mode==='monthly' ? '/mo' : '/cycle';
          if(progress<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      btnMonthly.addEventListener('click', ()=>setMode('monthly'));
      btnPackage.addEventListener('click', ()=>setMode('package'));

      // Quick calculator
      quickToggle.addEventListener('click', ()=>{
        setMode(mode==='monthly' ? 'package' : 'monthly');
      });
      quickPlan.addEventListener('change', updateQuickResult);
      function updateQuickResult(){
        const plan = quickPlan.value;
        const mapping = {seed:{monthly:49,package:240},grove:{monthly:129,package:600},orchard:{monthly:219,package:1000}};
        const value = mapping[plan][mode];
        quickResult.textContent = (mode==='monthly' ? '$'+value+' /mo' : '$'+value+' total');
      }

      // initialize
      setMode('monthly', false);
    })();
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Voices — Stories of habit wins</title>
  <style>
    :root{--bg:#fff;--muted:#5b6b5b;--accent:#7aa77a}
    body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto; margin:0;background:linear-gradient(180deg,#fbfff9,#ffffff);color:#0b1721}
    header{display:flex;justify-content:space-between;align-items:center;padding:20px 28px}
    .logo{width:46px;height:46px;border-radius:12px;background:linear-gradient(135deg,#7aa77a,#3b8fe6);display:flex;align-items:center;justify-content:center;color:white;font-weight:800}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none}
    .container{max-width:1000px;margin:18px auto;padding:20px}
    .lead{background:#fff;padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(10,20,30,0.04)}
    .gallery{display:flex;gap:18px;margin-top:18px}
    .carousel{flex:2;background:linear-gradient(180deg,#fff,#fbfffb);padding:18px;border-radius:12px;min-height:180px;position:relative}
    .card{padding:12px;border-radius:10px;background:rgba(255,255,255,0.8);height:100%;display:flex;flex-direction:column;justify-content:space-between}
    .quote{font-weight:700;font-size:18px}
    .by{font-size:13px;color:var(--muted)}
    .controls{display:flex;gap:8px;margin-top:12px}
    .dot{width:10px;height:10px;border-radius:50%;background:#dfeee0}
    .dot.active{background:var(--accent)}
    .badges{flex:1;background:linear-gradient(180deg,#fff,#fafdfa);padding:18px;border-radius:12px}
    .badge{display:inline-flex;gap:8px;align-items:center;padding:10px;border-radius:10px;margin:6px;background:#f6fff7;border:1px solid rgba(120,160,120,0.08);cursor:default}
    .badge svg{width:28px;height:28px}
    .tooltip{position:absolute;background:#0b1721;color:white;padding:8px;border-radius:8px;font-size:13px;opacity:0;transform:translateY(6px);transition:all 160ms ease}
    .cred-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}
    footer{padding:18px;text-align:center;color:var(--muted);font-size:13px}
    @media(max-width:820px){.gallery{flex-direction:column}.cred-grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">WC</div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Nest</a>
      <a href="about.html">Story</a>
      <a href="services.html">Care</a>
      <a href="programs.html">Tracts</a>
      <a href="pricing.html">Invest</a>
      <a href="testimonials.html" style="font-weight:800;color:#0b1721">Voices</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="container">
    <section class="lead">
      <h1 style="margin:0 0 6px">Real notes from people who built new rhythms</h1>
      <p style="margin:0;color:var(--muted)">Short snapshots of habit progress — each entry highlights the framework used and the clear outcome. We rotate a selection below and surface credibility markers to show where these stories came from.</p>
    </section>

    <section class="gallery">
      <div class="carousel">
        <div class="card" id="testimonialCard">
          <div>
            <div class="quote" id="quoteText">"I learned to anchor a 10-minute ritual that changed my mornings."</div>
            <div class="by" id="quoteBy">— Alex, product designer</div>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div style="color:var(--muted);font-size:13px">Framework: Tiny Habit + Stacking</div>
            <div class="controls" id="dots"></div>
          </div>
        </div>
        <div class="tooltip" id="tooltip" role="status"></div>
      </div>

      <aside class="badges">
        <h3 style="margin:0 0 8px">Proof Gallery & Credibility</h3>
        <div style="color:var(--muted);font-size:13px">We rotate testimonials; badges mark source and context — hover to learn more.</div>
        <div class="cred-grid" id="badgesGrid" style="margin-top:12px">
          <!-- badges rendered by JS -->
        </div>
        <div style="margin-top:12px;color:var(--muted);font-size:13px">All stories reflect outcomes from habit practice and coaching structures, not medical results.</div>
      </aside>
    </section>

  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto;padding:18px 28px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <div>Want your story featured? <a href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
    </div>
  </footer>

  <script>
    // Rotating testimonial gallery + badges with tooltips
    (function(){
      const testimonials = [
        {text:'"I learned to anchor a 10-minute ritual that changed my mornings."', by:'Alex, product designer', framework:'Tiny Habit + Stacking', badges:[{key:'workshop',label:'Local workshop',info:'Shared during a public workshop in {{CITY}}'},{key:'survey',label:'6-week survey',info:'Collected from cohort feedback forms (anonymized)'}]},
        {text:'"Small, three-minute habits gave me the energy to finish the day stronger."', by:'Priya, teacher', framework:'Micro-checklist', badges:[{key:'pod',label:'Podcast feature',info:'Discussed coaching approach on a wellness podcast'},{key:'case',label:'Case note',info:'Coach-collected progress notes during cohort'}]},
        {text:'"I finally built a steady bedtime rhythm — that one habit was a multiplier."', by:'Jordan, entrepreneur', framework:'Evening anchor', badges:[{key:'article',label:'Local article',info:'Profiled in city lifestyle article'},{key:'survey',label:'Cohort survey',info:'Participant-reported improvements in routine consistency'}]}
      ];

      const cardText = document.getElementById('quoteText');
      const cardBy = document.getElementById('quoteBy');
      const dots = document.getElementById('dots');
      const badgesGrid = document.getElementById('badgesGrid');
      const tooltip = document.getElementById('tooltip');

      let idx = 0;
      function render(i){
        const t = testimonials[i];
        cardText.textContent = t.text;
        cardBy.textContent = '— ' + t.by + ' • ' + t.framework;
        // dots
        dots.innerHTML = '';
        testimonials.forEach((_,j)=>{
          const d = document.createElement('div');
          d.className = 'dot' + (j===i? ' active':'');
          d.title = 'Show testimonial ' + (j+1);
          d.style.cursor = 'pointer';
          d.addEventListener('click', ()=>{ idx=j; render(idx); });
          dots.appendChild(d);
        });
        // badges
        badgesGrid.innerHTML = '';
        t.badges.forEach(b=>{
          const el = document.createElement('div');
          el.className = 'badge';
          el.setAttribute('data-info', b.info);
          el.innerHTML = `
            <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="3" width="18" height="18" rx="4" fill="#e9f6e9" stroke="#bde0b8"></rect><path d="M7 12h10M7 8h4" stroke="#7aa77a" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"></path></svg>
            <div style="font-size:13px">${b.label}</div>
          `;
          el.addEventListener('mouseenter', (ev)=>showTooltip(ev,b.info));
          el.addEventListener('mouseleave', hideTooltip);
          badgesGrid.appendChild(el);
        });
      }

      function showTooltip(ev,info){
        tooltip.textContent = info.replace('{{CITY}}','{{CITY}}');
        const rect = ev.target.getBoundingClientRect();
        tooltip.style.left = (rect.left + window.scrollX + rect.width/2 - 80) + 'px';
        tooltip.style.top = (rect.top + window.scrollY - 46) + 'px';
        tooltip.style.opacity = '1';
        tooltip.style.transform = 'translateY(0)';
      }
      function hideTooltip(){ tooltip.style.opacity='0'; tooltip.style.transform='translateY(6px)'; }

      // auto-rotate every 6s
      render(0);
      setInterval(()=>{ idx = (idx+1) % testimonials.length; render(idx); }, 6000);

    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Reserve a spot — Cohort booking</title>
  <style>
    :root{--bg:#fff;--accent:#6fa86c;--muted:#5b6b5b}
    body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto;margin:0;background:linear-gradient(180deg,#fff,#f7fdf7);color:#0b1721}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 26px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,#6fa86c,#3e92df);display:flex;align-items:center;justify-content:center;color:white;font-weight:800}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .wrap{max-width:960px;margin:20px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .form-card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 28px rgba(10,20,30,0.04)}
    label{display:block;margin-bottom:6px;font-weight:600}
    input,select,textarea{width:100%;padding:10px;border-radius:10px;border:1px solid #e9f6ea;margin-bottom:12px}
    .row{display:flex;gap:8px}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:10px;border:0;cursor:pointer;font-weight:700}
    .side{background:linear-gradient(180deg,#fff,#fbfffb);padding:16px;border-radius:12px}
    .cohort-list{display:flex;flex-direction:column;gap:8px}
    .cohort{padding:10px;border-radius:10px;border:1px solid #eef7ee;cursor:pointer}
    .cohort.active{background:#f0fff2;border-color:#cdeec7}
    .small{font-size:13px;color:var(--muted)}
    footer{padding:18px;text-align:center;color:var(--muted);font-size:13px}
    @media(max-width:820px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">WC</div>
      <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Nest</a>
      <a href="about.html">Story</a>
      <a href="services.html">Care</a>
      <a href="programs.html">Tracts</a>
      <a href="pricing.html">Invest</a>
      <a href="testimonials.html">Voices</a>
      <a href="book.html" style="font-weight:800">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section class="form-card" aria-labelledby="bookTitle">
        <h2 id="bookTitle">Reserve your spot in the next cohort</h2>
        <p class="small">We run small cohorts focused on habit frameworks and steady outcomes. Choose a cohort and your preferred payment option.</p>

        <form id="bookingForm">
          <div class="row">
            <div style="flex:1">
              <label for="name">Full name</label>
              <input id="name" name="name" placeholder="Your name" required />
            </div>
            <div style="width:160px">
              <label for="phone">Phone</label>
              <input id="phone" name="phone" placeholder="{{PHONE}}" />
            </div>
          </div>

          <label for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@email.com" required />

          <label for="cohort">Choose cohort</label>
          <select id="cohort" name="cohort" required>
            <option value="may-6">May 6 • Morning Rhythm • 6 weeks</option>
            <option value="jun-10">Jun 10 • Evening Reset • 6 weeks</option>
            <option value="jul-8">Jul 8 • Deep Rebuild • 12 weeks</option>
          </select>

          <label>Payment preference</label>
          <div style="display:flex;gap:8px;margin-bottom:12px">
            <button type="button" class="btn" id="payMonthly">Monthly</button>
            <button type="button" class="btn" id="payPackage" style="background:#fff;color:var(--accent);border:1px solid rgba(110,170,110,0.18)">Package</button>
          </div>

          <label for="notes">Notes (goals or habits you want to focus)</label>
          <textarea id="notes" name="notes" rows="4" placeholder="A couple sentences about the outcomes you're after"></textarea>

          <div style="display:flex;gap:8px;align-items:center">
            <button class="btn" type="submit">Hold my place</button>
            <div style="font-size:13px;color:var(--muted)">Or call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
          </div>

          <input type="hidden" name="paymentStyle" id="paymentStyle" value="monthly" />
        </form>
      </section>

      <aside class="side">
        <h3 style="margin-top:0">Upcoming cohorts</h3>
        <div class="cohort-list" id="cohortList">
          <div class="cohort active" data-plan="may-6">May 6 • Morning Rhythm — 6 weeks<br><span class="small">Mon & Wed, 8:00–9:00</span></div>
          <div class="cohort" data-plan="jun-10">Jun 10 • Evening Reset — 6 weeks<br><span class="small">Tue & Thu, 7:30–8:30</span></div>
          <div class="cohort" data-plan="jul-8">Jul 8 • Deep Rebuild — 12 weeks<br><span class="small">Wed, 6:30–8:00</span></div>
        </div>

        <hr style="border:none;border-top:1px solid #eef4ee;margin:12px 0">
        <div>
          <div style="font-weight:700">Why cohorts?</div>
          <div class="small" style="margin-top:6px;color:var(--muted)">A focused cohort gives structure, peer accountability, and a repeatable framework to carry habits forward after the cycle ends.</div>
        </div>

        <div style="margin-top:12px">
          <div style="font-weight:700">Quick budget guide</div>
          <div class="small" style="margin-top:6px;color:var(--muted)" id="budgetNote">Monthly: from $129 / mo • Package: from $600</div>
        </div>
      </aside>
    </div>
  </main>

  <footer>
    <div style="max-width:900px;margin:0 auto;padding:18px 28px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
      <div class="small">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </div>
  </footer>

  <script>
    // Booking form micro-interactions
    (function(){
      const payMonthly = document.getElementById('payMonthly');
      const payPackage = document.getElementById('payPackage');
      const paymentStyle = document.getElementById('paymentStyle');
      const cohortList = document.getElementById('cohortList');
      const cohorts = Array.from(cohortList.querySelectorAll('.cohort'));
      const cohortSelect = document.getElementById('cohort');
      const budgetNote = document.getElementById('budgetNote');

      function setPayment(style){
        paymentStyle.value = style;
        if(style==='monthly'){
          payMonthly.style.background = 'var(--accent)'; payMonthly.style.color='#fff';
          payPackage.style.background = '#fff'; payPackage.style.color='var(--accent)';
        } else {
          payPackage.style.background = 'var(--accent)'; payPackage.style.color='#fff';
          payMonthly.style.background = '#fff'; payMonthly.style.color='var(--accent)';
        }
        updateBudgetNote();
      }

      payMonthly.addEventListener('click', ()=>setPayment('monthly'));
      payPackage.addEventListener('click', ()=>setPayment('package'));

      cohorts.forEach(c=>c.addEventListener('click', ()=>{
        cohorts.forEach(x=>x.classList.remove('active'));
        c.classList.add('active');
        const plan = c.getAttribute('data-plan');
        Array.from(cohortSelect.options).forEach(o=>{ o.selected = (o.value===plan); });
        updateBudgetNote();
      }));

      function updateBudgetNote(){
        const plan = cohortSelect.value;
        const mapping = { 'may-6':{monthly:129,package:600}, 'jun-10':{monthly:129,package:600}, 'jul-8':{monthly:219,package:1000} };
        const style = paymentStyle.value || 'monthly';
        const val = mapping[plan][style];
        budgetNote.textContent = style==='monthly' ? 'Monthly: from $' + val + ' /mo' : 'Package: $' + val + ' total';
      }

      // form submit (demo) — prevents real send, shows a friendly confirmation snippet
      const form = document.getElementById('bookingForm');
      form.addEventListener('submit', function(e){
        e.preventDefault();
        const data = new FormData(form);
        const name = data.get('name');
        const cohort = data.get('cohort');
        const payment = data.get('paymentStyle');
        alert('Thanks, ' + name + '! We received your request for ' + cohort + ' ('+payment+'). We will reach out via email to confirm.');
        form.reset();
        setPayment('monthly');
      });

      // initialize
      setPayment('monthly');
      updateBudgetNote();
    })();
  </script>
</body>
</html>"} 
